import * as T from './assets/three.js';
import {FontLoader} from './assets/addons/FontLoader.js';
import {TextGeometry} from './assets/addons/TextGeometry.js';
let fontPromise;
// Cross section follows the official oblique view: a flattened rounded rectangle.
function perimeter(w,d,r,segments=20){r=Math.min(r,w*.49,d*.49);const out=[];for(let j=0;j<4;j++){const centers=[[w/2-r,d/2-r],[-w/2+r,d/2-r],[-w/2+r,-d/2+r],[w/2-r,-d/2+r]],cx=centers[j][0],cz=centers[j][1],start=j*Math.PI/2;for(let i=0;i<segments;i++){const a=start+i/segments*Math.PI/2;out.push([cx+Math.cos(a)*r,cz+Math.sin(a)*r])}}return out}
function shell(w,h,d,r,topBevel,bottomBevel){const rings=[],steps=14;topBevel=Math.min(topBevel,d*.46,h*.45);bottomBevel=Math.min(bottomBevel,d*.46,h*.45);
for(let i=0;i<=steps;i++){const a=i/steps*Math.PI/2;rings.push({y:bottomBevel*(1-Math.cos(a)),inset:bottomBevel*(1-Math.sin(a))})}rings.push({y:h-topBevel,inset:0});for(let i=1;i<=steps;i++){const a=i/steps*Math.PI/2;rings.push({y:h-topBevel+topBevel*Math.sin(a),inset:topBevel*(1-Math.cos(a))})}
const n=80,p=[],uv=[],indices=[];for(const ring of rings){const edge=perimeter(Math.max(.02,w-ring.inset*2),Math.max(.02,d-ring.inset*2),Math.max(.008,r-ring.inset));edge.forEach(([x,z],j)=>{p.push(x,ring.y,z);uv.push(j/n,ring.y/h)})}for(let k=0;k<rings.length-1;k++)for(let j=0;j<n;j++){const a=k*n+j,b=k*n+(j+1)%n,c=(k+1)*n+j,d=(k+1)*n+(j+1)%n;indices.push(a,c,b,b,c,d)}
const bottom=p.length/3;p.push(0,0,0);uv.push(.5,.5);const top=p.length/3;p.push(0,h,0);uv.push(.5,.5);for(let j=0;j<n;j++){indices.push(bottom,j,(j+1)%n);const a=(rings.length-1)*n+j,b=(rings.length-1)*n+(j+1)%n;indices.push(top,b,a)}
const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(p,3));geo.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geo.setIndex(indices);geo.computeVertexNormals();geo.computeBoundingBox();return geo}
function printing(texts,w,h,color){const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=700;const c=canvas.getContext('2d');c.textAlign='center';c.textBaseline='middle';c.fillStyle=color;for(const line of texts){c.font=line.font+'px Arial';c.fillText(line.text,800,line.y,1500)}const map=new T.CanvasTexture(canvas);map.colorSpace=T.SRGBColorSpace;map.anisotropy=8;const mesh=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1}));return mesh}
export async function createSkinVeil(renderer){const root=new T.Group();root.name='雪纱丝柔修颜隔离乳 No.40 · 30ml';const W=1.005,D=.70,H=3,bodyH=1.695,gap=.006;
const capMaterial=new T.MeshPhysicalMaterial({color:0xbca4d6,metalness:0,roughness:.18,clearcoat:1,clearcoatRoughness:.08,sheen:.15,sheenColor:0xeaddff,sheenRoughness:.4,ior:1.48,envMapIntensity:.95});
const coreMaterial=new T.MeshPhysicalMaterial({color:0xb296ca,metalness:0,roughness:.39,clearcoat:.55,clearcoatRoughness:.27,envMapIntensity:.8});
const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src='assets/skin-veil-reference.png'});const grain=document.createElement('canvas');grain.width=grain.height=192;const c=grain.getContext('2d');c.drawImage(img,img.width*.24,img.height*.75,img.width*.48,img.height*.13,0,0,192,192);const a=c.getImageData(0,0,192,192),raw=a.data,out=c.createImageData(192,192);for(let y=0;y<192;y++)for(let x=0;x<192;x++){let sum=0,n=0;for(let yy=Math.max(0,y-4);yy<=Math.min(191,y+4);yy+=2)for(let xx=Math.max(0,x-4);xx<=Math.min(191,x+4);xx+=2){const k=(yy*192+xx)*4;sum+=(raw[k]+raw[k+1]+raw[k+2])/3;n++}const k=(y*192+x)*4,diff=(raw[k]+raw[k+1]+raw[k+2])/3-sum/n,v=T.MathUtils.clamp(220+diff*1.5,180,250);out.data.set([v,v,v,255],k)}c.putImageData(out,0,0);const bump=new T.CanvasTexture(grain);bump.wrapS=bump.wrapT=T.RepeatWrapping;bump.repeat.set(3,3);bump.anisotropy=renderer.capabilities.getMaxAnisotropy();coreMaterial.bumpMap=bump;coreMaterial.bumpScale=.0018;
const core=new T.Mesh(shell(.84,bodyH-.16,.53,.19,.012,.18),coreMaterial);core.position.y=.16;core.name='紫色磨砂内胆';root.add(core);
const clearMaterial=new T.MeshPhysicalMaterial({color:0xf3e8ff,metalness:0,roughness:.075,transmission:.76,thickness:.07,ior:1.47,clearcoat:1,clearcoatRoughness:.08,attenuationColor:0xdfcafa,attenuationDistance:1.6,envMapIntensity:1.0,transparent:true,opacity:1,depthWrite:false});const glass=new T.Mesh(shell(W,bodyH,D,.235,.012,.235),clearMaterial);glass.name='透明外壁与加厚圆角底座';glass.castShadow=false;glass.userData.noCastShadow=true;root.add(glass);
const cap=new T.Mesh(shell(W,H-bodyH-gap,D,.235,.255,.009),capMaterial);cap.position.y=bodyH+gap;cap.name='独立圆角珠光紫盖体';root.add(cap);
// A narrow closure line is visible in the user's image and official angle image.
const seamMat=new T.MeshStandardMaterial({color:0x947caf,roughness:.38});const seam=new T.Mesh(shell(W*.986,.008,D*.986,.23,.001,.001),seamMat);seam.position.y=bodyH-.001;seam.name='盖体闭合细缝';root.add(seam);
// Real raised glyph geometry, aligned from bottom to top as in the primary reference.
fontPromise ||=new FontLoader().loadAsync('assets/fonts/helvetiker_regular.typeface.json');const font=await fontPromise;const raisedText=new TextGeometry('LANEIGE',{font,size:.095,height:.003,curveSegments:5,bevelEnabled:true,bevelSize:.0009,bevelThickness:.0008,bevelSegments:2});const embossGeo=new T.BufferGeometry().copy(raisedText);raisedText.dispose();embossGeo.computeBoundingBox();const b=embossGeo.boundingBox,center=b.getCenter(new T.Vector3());embossGeo.translate(-center.x,-center.y,0);const emboss=new T.Mesh(embossGeo,capMaterial.clone());emboss.rotation.z=Math.PI/2;emboss.position.set(0,2.315,D/2+.0005);emboss.name='盖面竖向 LANEIGE 浮雕字';root.add(emboss);
const brand=printing([{text:'LANEIGE',font:280,y:350}],.62,.21,'#95869f');brand.position.set(0,1.401,D/2+.003);brand.name='瓶身 LANEIGE 独立印刷';root.add(brand);
const label=printing([{text:'SKIN VEIL',font:230,y:245},{text:'BASE_EX',font:210,y:450}],.61,.33,'#95869f');label.position.set(0,.614,D/2+.003);label.name='SKIN VEIL / BASE_EX 独立印刷';root.add(label);
// The bottom perimeter is separate from the contents, preserving the clear-wall impression.
const baseMat=clearMaterial.clone();baseMat.transmission=.48;baseMat.thickness=.12;const foot=new T.Mesh(shell(.94,.07,.64,.22,.025,.025),baseMat);foot.position.y=.018;foot.name='透明厚壁底缘';foot.castShadow=false;foot.userData.noCastShadow=true;root.add(foot);
root.traverse(n=>{if(n.isMesh&&n!==glass&&n!==foot){n.castShadow=true;n.receiveShadow=true}});brand.castShadow=label.castShadow=false;root.userData={buildMethod:'researched-skin-veil-40',productKey:'laneige-skin-veil-base-ex-40-30ml',referenceBasis:'用户原图 + 中国官网 No.40 正面 / 斜视 / 高清视觉图',depthEstimate:'侧面厚度按官网斜视图拟合，非毫米尺寸',unknownFaces:['背标','完整底贴','开盖泵头']};return root;
}
